from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.verification.auto_correct_delta_commissioning.delta_file_operations import \
    DeltaFileOperations
from taf.ul.trs_e2e_fw.lib.utils.verification.auto_correct_delta_commissioning.nidd_file_operations import \
    NIDDFileOperations

logger = BackgroundLogger.Instance()


class AutoCorrectionTool:
    def __init__(self):
        self.nidd_content = None
        self.delta_json_content = None
        self.output_delta_file = None
        self.delta_operations = DeltaFileOperations()
        self.nidd_operations = NIDDFileOperations()

    def compare_delta_against_nidd(self, **kwargs):
        """
        Function compares given delta file with latest NIDD file.

        Latest nidd file depends on the active build on the BTS. nidd file will be fetched from BTS configuration.
        Refer to `_fetch_nidd_content` for more information on NIDD file

        :param kwargs:
            delta_file: str, Name of the delta file with extension
            local_ip: str, ip to communicate with locally configured BTS

        :returns path to auto corrected delta json file
        :rtype :string
        """
        delta_filename = kwargs["delta_file"]
        module = kwargs.get("module", "webem").lower()

        self.output_delta_file = delta_filename.replace(".json", "_autocorrected_file.json")

        local_ip = kwargs.get("local_ip", "127.0.0.1")
        self.nidd_content = self.nidd_operations.fetch_nidd_content(local_ip=local_ip)
        self.delta_json_content = self.delta_operations.fetch_delta_content("{}".format(delta_filename))

        logger.debug(" #### Old delta file :::: {}".format(delta_filename))
        logger.debug(" #### New delta file :::: {}".format(self.output_delta_file))
        for delta_moc in self.delta_json_content:
            logger.debug("\n\n################# Check delta for MOC {} ###############\n".format(delta_moc['distName']))
            parent_mo = delta_moc['distName'].split("/")[-1].split("-")[0]
            if parent_mo in self.nidd_content:
                nidd_param_content = self.nidd_operations.get_nidd_parameter(parent_mo)
            else:
                raise Exception("{} is not present in NIDD".format(parent_mo))

            delta_content = self.delta_operations.fetch_updated_delta_content(delta_moc)
            logger.debug("Delta content: {}".format(delta_content))

            if delta_moc['operation'] == 'create':
                self.add_meta_information(parent_mo=parent_mo, delta_moc=delta_moc)

                logger.info("\n################# Performing create operation for MOC {} ###############\n".format(
                    delta_moc['distName']))

                logger.info("\n############### Fetching parameters to be removed from delta (Present in Delta but not"
                            "present in NIDD) ###############\n")

                to_be_removed = self._fetch_delta_param_to_be_removed(delta_content=delta_content,
                                                                      nidd_content=nidd_param_content)
                if to_be_removed:
                    logger.info("Delta params {} are not present in NIDD. Check if these parameters are actually"
                                "removed or parameter name has been updated in latest NIDD.".format(to_be_removed))
                    self.delta_operations.remove_parameter_from_delta(delta=delta_moc, parameter_dict=to_be_removed)
                else:
                    logger.debug("No parameters are identified for removal")

                if module == "netact":
                    self.delta_operations.write_to_json_file(input_file=self.delta_json_content,
                                                             output_file=self.output_delta_file)
                else:
                    logger.info("\n############### Fetching parameters to be added to delta (Present in NIDD but "
                                "missing from delta) ###############\n")
                    to_be_added = self._fetch_delta_param_to_be_added(delta_content=delta_content,
                                                                      nidd_content=nidd_param_content)
                    if to_be_added:
                        self._add_parameter_to_delta(parent_mo=parent_mo, delta=delta_moc, parameter_dict=to_be_added)
                    else:
                        pass
                    self._identify_and_remove_unmodifiable_param(parent_mo=parent_mo, delta=delta_moc)
            if delta_moc['operation'] == 'update':
                logger.debug("\n\n################# Performing update operation on MOC {} ###############\n".format(
                    delta_moc['distName']))
                to_be_removed = self._fetch_delta_param_to_be_removed(delta_content=delta_content,
                                                                      nidd_content=nidd_param_content)
                if to_be_removed:
                    logger.debug("Delta params {} are not present in NIDD. Check if these parameters are actually "
                                 "removed or parameter name has been updated as per NIDD "
                                 "definition.".format(to_be_removed))
                    self.delta_operations.remove_parameter_from_delta(delta=delta_moc, parameter_dict=to_be_removed)
                    self._identify_and_remove_modification_type_change_param(parent_mo=parent_mo, delta=delta_moc)
                else:
                    logger.debug("delta content is present in NIDD")
                if module == "netact":
                    self.delta_operations.write_to_json_file(input_file=self.delta_json_content,
                                                             output_file=self.output_delta_file)
            if delta_moc['operation'] == 'delete':
                logger.warn("\n\n################# Performing delete operation on MOC {} is not yet supported by auto "
                            "correction logic###############\n\n".format(delta_moc['distName']))
                return delta_filename
        return self.output_delta_file

    def _identify_and_remove_modification_type_change_param(self, parent_mo, delta):
        """
        Functions identifies and removes parameters whose modification type is set to zero.

        :param parent_mo: str, parent managed object to identify the MOC on which action need to be taken
        :param delta: dict, Delta moc from where parameters are to be removed

        :return None
        :rtype NA
        """
        delta_content = self.delta_operations.fetch_updated_delta_content(delta=delta)
        to_be_removed = {}
        for param in delta['parameters']:
            if not self.nidd_content[parent_mo]['params'][param['parameterName']]['modificationType']:
                logger.debug("Modification type restricts parameter {} to be added to delta".format(
                    param['parameterName']))
                to_be_removed[param['parameterName']] = delta_content[param['parameterName']]
        self.delta_operations.remove_parameter_from_delta(delta=delta, parameter_dict=to_be_removed)

    def _fetch_delta_param_to_be_removed(self, delta_content, nidd_content):
        """
        Compare delta content against nidd content, mark delta parameters that are not part of nidd content has to be
        removed.

        Here parameters that are not found in nidd are assumed as deleted from NIDD.
        There could also be a case that parameter name was modified in latest nidd(We have not got sufficient data to
        check modified parameter).

        :param delta_content: json dict, data file content
        :param nidd_content: json dict, nidd file content

        :returns: Parameter dictionary to be removed from delta file
            Key defines the name of the parameter and Value defines the complexity of the parameter.
            Parameter of type Simple, has value=None
            Parameter of type Complex has value=[], each item in list is again a parameter name

           example output: {'cPlaneIpAddrCtrl': None, 'plmnId': ['mncLength'] }
            "cPlaneIpAddrCtrl" is a simple parameter
            'plmnId" is a complex parameter, which contains 'mncLength' parameter to be removed from existing delta file

        :rtype: dict
        """
        to_be_removed = {}
        for key, value in delta_content.items():
            if key not in nidd_content.keys():
                to_be_removed[key] = value
            elif key in nidd_content.keys() and isinstance(value, list):
                if list(set(value).difference(set(nidd_content[key]))):
                    to_be_removed[key] = list(set(value).difference(set(nidd_content[key])))
        logger.info("Parameter to be removed from delta: {}".format(to_be_removed))
        return to_be_removed

    def _fetch_delta_param_to_be_added(self, delta_content, nidd_content):
        """
        Compare nidd content against delta content, mark nidd parameters that are not part of delta content as to be
        added to delta file.

        Here parameters that are not found in delta are assumed as new parameter added in latest nidd..
        There could also be a case that parameter name was modified in latest nidd(We have not got sufficient data to
        check modified parameter).

        :param delta_content: json dict, delta file content.
        :param nidd_content: json dict, nidd file content.

        :returns: Parameter dictionary to be added to delta file
            Key defines the name of the parameter and Value defines the complexity of the parameter.
            Parameter of type Simple, has value=None
            Parameter of type Complex has value=[], each item in list is again a parameter name

           example output: {'cPlaneIpAddrCtrl': None, 'plmnId': ['mncLength'] }
            "cPlaneIpAddrCtrl" is a simple parameter
            'plmnId" is a complex parameter, which contains 'mncLength' parameter
            to be added to existing delta file

        :rtype: dict
        """
        to_be_added = {}
        for key, value in nidd_content.items():
            if key not in delta_content.keys():
                if isinstance(value, list) or value is None:
                    to_be_added[key] = value
            elif value and value not in delta_content.values():
                to_be_added[key] = list(set(value).difference(set(delta_content[key])))
        logger.info("Parameter to be added to delta: {}".format(to_be_added))
        return to_be_added

    def _add_parameter_to_delta(self, parent_mo, delta, parameter_dict):
        """
        This function add parameter to delta file

        :param parent_mo: str,  Managed Object to fetch the parameters.
        :param parameter_dict: dict, Parameters to be added to delta file. Refer to documentation of
            `_fetch_delta_param_to_be_added` to know more on this parameter
        :param delta: dict, Delta moc to add given parameter_dict

        :returns None
        :rtype NA
        """
        logger.info("Parameters identified to be added into Delta {}".format(parameter_dict))
        for key, value in parameter_dict.items():
            if not value:
                self._add_simple_parameter_to_delta(parent_mo=parent_mo, delta=delta, parameter_name=key)
            else:
                self._add_complex_parameter_to_delta(parent_mo=parent_mo, delta=delta, parameter_name=key,
                                                     sub_paramater_list=value)
        logger.debug("####### json content {}".format(self.delta_json_content))

    def _add_simple_parameter_to_delta(self, parent_mo, delta, parameter_name):
        """
        Function adds simple parameter structure to the given delta file

        :param parent_mo: str, Parent managed object
        :param delta: dict, Delta file to be updated, simple parameter will be added to this file
        :param parameter_name: str, Simple parameter name to be added


        :returns None
        :rtype NA

        """
        if self.nidd_content[parent_mo]['params'][parameter_name]['modificationType'] != 0:
            if self.nidd_operations.is_default_present_in_nidd(parent_mo=parent_mo, parameter=parameter_name):
                add_new_parameter = {"operation": "update", "parameterName": parameter_name,
                                     "value": self.nidd_operations.get_parameters_default_value_from_nidd(
                                         parent_mo=parent_mo, parameter=parameter_name)}
                delta['parameters'].append(add_new_parameter)
                logger.debug("New dict to be added {}".format(add_new_parameter))
            else:
                logger.debug("Default value is not present for simple parameter {}. Check if Enumeration or minIncl is"
                             "present".format(parameter_name))
                add_new_parameter = {"operation": "update", "parameterName": parameter_name,
                                     "value": self.nidd_operations.fetch_new_default_value(parent_mo=parent_mo,
                                                                                           parameter=parameter_name)}
                self.delta_operations.update_delta_content(delta=delta, parameter_content=add_new_parameter)
        else:
            logger.debug("Modification type restricts parameter {} to be added to delta".format(parameter_name))
        self.delta_operations.write_to_json_file(input_file=self.delta_json_content, output_file=self.output_delta_file)

    def _add_complex_parameter_to_delta(self, parent_mo, delta, parameter_name, sub_paramater_list):
        """
        Function adds complex parameter structure to the given delta file

        :param parent_mo: str, Parent managed object
        :param delta: dict, Delta file to be updated, complex parameter will be added to this file
        :param parameter_name: str, Complex parameter name to be added
        :param sub_paramater_list: list, list of sub parameters to be added under complex parameter. If single sub
            parameter is to be added it is also passed in a list.

        :returns None
        :rtype NA
        """
        for complex_param in sub_paramater_list:
            if self.nidd_operations.is_default_present_in_nidd(parent_mo=parent_mo, parameter=parameter_name,
                                                               sub_parameter=complex_param):
                add_new_parameter = {"operation": "update", "parameterName": parameter_name,
                                     "value": [
                                         {complex_param: self.nidd_operations.get_parameters_default_value_from_nidd(
                                             parent_mo=parent_mo, parameter=parameter_name,
                                             sub_parameter=complex_param)}]}
                self.delta_operations.update_delta_content(delta=delta, parameter_content=add_new_parameter)
            else:
                logger.debug("Default value is not present for parameter {}. Checking for Enumeration or minIncl to "
                             "pick default value".format(parameter_name))
                add_new_parameter = {"operation": "update", "parameterName": parameter_name,
                                     "value": [{complex_param: self.nidd_operations.fetch_new_default_value(
                                         parent_mo=parent_mo, parameter=parameter_name, sub_parameter=complex_param)}]}
                self.delta_operations.update_delta_content(delta=delta, parameter_content=add_new_parameter)

        self.delta_operations.write_to_json_file(input_file=self.delta_json_content, output_file=self.output_delta_file)

    def _identify_and_remove_unmodifiable_param(self, parent_mo, delta):
        """
        This function removes the parameter with creation priority 2

        :param parent_mo: str, parent managed object
        :param delta: dict, delta moc to remove unmodifiable parameter

        :returns: None
        :rtype: NA
        """
        delta_content = self.delta_operations.fetch_updated_delta_content(delta=delta)
        to_be_removed = {}
        for param in delta['parameters']:
            if self.nidd_content[parent_mo]['params'][param['parameterName']]['creationPriority'] == 2:
                print("Creation priority restricts parameter {} to be added to delta".format(param['parameterName']))
                to_be_removed[param['parameterName']] = delta_content[param['parameterName']]

    def add_meta_information(self, parent_mo, delta_moc):
        """
        This function adds NIDD release information to the delta MOC

        :param delta_moc: dict, delta moc add the meta information
        :param parent_mo: str, Parent managed object

        :returns: None
        :rtype: NA
        """

        if not delta_moc.get("meta_params"):
            delta_moc["meta_params"] = {"meta_class": "", "meta_version": ""}

        delta_meta_version = delta_moc["meta_params"]["meta_version"]
        nidd_meta_version = self.nidd_content[parent_mo]["release"]
        logger.info("release version in delta is: {}, nidd is: {}".format(
            delta_meta_version, nidd_meta_version))
        if delta_meta_version != nidd_meta_version:
            delta_moc["meta_params"]["meta_version"] = nidd_meta_version